#[tokio::test(flavor = "current_thread")]
async fn w336_config_diagnostics_one_file_snapshot() {
    let root=tempfile::tempdir().unwrap();
    let cwd=tempfile::tempdir().unwrap();
    let named=root.path().join("named.config.toml");
    let dir=root.path().join("directory");
    let missing=root.path().join("missing.config.toml");
    let files=["a.json","z.toml"];
    std::fs::write(&named,"# fixture\n").unwrap();
    std::fs::create_dir(&dir).unwrap();
    for f in ["z.toml","a.json","ignored.TOML","readme.txt"] {
        std::fs::write(dir.join(f),"# fixture\n").unwrap();
    }
    std::fs::create_dir(dir.join("nested.toml")).unwrap();
    std::fs::write(dir.join("nested.toml/inside.toml"),"").unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(dir.join("a.json"),dir.join("m.json")).unwrap();
    let mut ordered=files.into_iter().map(|f|dir.join(f)).collect::<Vec<_>>();
    #[cfg(unix)]
    ordered.insert(1, dir.join("m.json"));
    let inline=std::path::PathBuf::from(format!("{}#agent=/fixture",named.display()));

    let cases=[
        ("none",None,vec![]),
        ("named",Some(named.clone()),vec![named.clone()]),
        ("inline",Some(inline),vec![named]),
        ("directory",Some(dir),ordered),
        ("missing",Some(missing),vec![]),
    ];
    for (kind,path,files) in cases {
        let expected=files.iter().map(|path|path.display().to_string()).collect::<Vec<_>>();
        let server=AgentAppServer::launch(config(),cwd.path().to_owned(),path.as_deref()).await.unwrap();
        crate::app_server::config_summary::FILE_LIST_CALLS.with(|calls|calls.set(0));
        let result=server.local_config_summary().await;
        let calls=crate::app_server::config_summary::FILE_LIST_CALLS.with(|calls|calls.get());
        assert_eq!(result["config_files"],json!(expected));
        assert_eq!(result["config_path"],json!(path.as_ref().map(|p|p.display().to_string())));
        let display=result["display_text"].as_str().unwrap();
        let prefix=format!("Config summary\nconfig path: {}\n", path.as_ref().map(|p|p.display().to_string()).unwrap_or("(default discovery / none)".into()));
        let mut section=prefix;
        if !expected.is_empty() {
            section.push_str("config files:\n");
            for name in &expected {section.push_str(&format!("  - {name}\n"));}
        }
        section.push_str("cwd: ");
        assert!(display.starts_with(&section), "{display}");
        if let Some(dir)=std::env::var_os("W336_WITNESS_DIR") {
            let mut stable=serde_json::to_string(&result).unwrap();
            if let Some(session)=result["session_dir"].as_str() {stable=stable.replace(session,"<session>");}
            stable=stable.replace(root.path().to_str().unwrap(),"<fixture>").replace(cwd.path().to_str().unwrap(),"<cwd>");
            std::fs::write(std::path::PathBuf::from(dir).join(format!("{kind}.json")),stable).unwrap();
        }
        eprintln!("W336 {kind} {calls} {}",expected.len());
        server.shutdown().await;
    }
}
